//! Offline release signing tool. Private keys never enter an application package.
use std::{fs,path::Path};
use base64::{Engine,engine::general_purpose::STANDARD};
use ed25519_dalek::{SigningKey,Signer};
use rand::RngCore;
fn main(){if let Err(e)=run(){eprintln!("{e}");std::process::exit(1);}}
fn run()->Result<(),String>{let args:Vec<String>=std::env::args().collect();match args.get(1).map(String::as_str){
 Some("keygen")=>{let target=Path::new(args.get(2).ok_or("Usage: FloatboardRelease keygen <private-key-path>")?);if target.exists(){return Err("Refusing to replace an existing private key".into());}let mut secret=[0u8;32];rand::rngs::OsRng.fill_bytes(&mut secret);let key=SigningKey::from_bytes(&secret);use std::io::Write;let mut file=fs::OpenOptions::new().create_new(true).write(true).open(target).map_err(|_|"Private key path must be a protected writable location outside repository")?;file.write_all(STANDARD.encode(secret).as_bytes()).map_err(|_|"Key save failed")?;file.sync_all().map_err(|_|"Key sync failed")?;println!("FLOATBOARD_UPDATE_PUBLIC_KEY={}",STANDARD.encode(key.verifying_key().to_bytes()));Ok(())},
 Some("sign")=>{let path=Path::new(args.get(2).ok_or("Usage: FloatboardRelease sign <manifest.json> <signature.sig>")?);let out=Path::new(args.get(3).ok_or("Signature path missing")?);let keypath=std::env::var_os("FLOATBOARD_UPDATE_PRIVATE_KEY_FILE").ok_or("Set FLOATBOARD_UPDATE_PRIVATE_KEY_FILE to a protected external key file")?;let text=fs::read_to_string(keypath).map_err(|_|"Private key unreadable")?;let secret: [u8;32]=STANDARD.decode(text.trim()).map_err(|_|"Invalid key encoding")?.try_into().map_err(|_|"Invalid private key size")?;let key=SigningKey::from_bytes(&secret);let expected=std::env::var("FLOATBOARD_UPDATE_PUBLIC_KEY").map_err(|_|"Set matching FLOATBOARD_UPDATE_PUBLIC_KEY before signing")?;if STANDARD.encode(key.verifying_key().to_bytes())!=expected.trim(){return Err("Signing private key does not match build public key".into());}let bytes=fs::read(path).map_err(|_|"Manifest unreadable")?;let _:serde_json::Value=serde_json::from_slice(&bytes).map_err(|_|"Manifest invalid JSON")?;let signature=key.sign(&bytes);fs::write(out,STANDARD.encode(signature.to_bytes())).map_err(|_|"Signature save failed")?;println!("Signed manifest; private key not exported");Ok(())},
 _=>Err("Usage: FloatboardRelease keygen <external-private-key-path> | sign <manifest.json> <signature.sig>".into())}}
